from django.shortcuts import render, get_object_or_404
import json
from django.http import JsonResponse
from django.views.decorators.csrf import csrf_exempt
import requests
from django.views.decorators.http import require_GET

from .models import Coin, Banknote, Order, OrderItem

def index(request):
    coins = Coin.objects.all()
    banknotes = Banknote.objects.all()

    # Фильтрация по году (если год передан в GET-запросе)
    year_filter = request.GET.get('year')
    if year_filter:
        coins = coins.filter(year=year_filter)
        banknotes = banknotes.filter(year=year_filter)

    return render(request, 'shop/index.html', {'coins': coins, 'banknotes': banknotes})

def coin_detail(request, pk):
    coin = get_object_or_404(Coin, pk=pk)
    return render(request, "shop/coin_detail.html", {"coin": coin})
def favorites(request):
    favorites_ids = request.COOKIES.get('favorites', '[]')  # Получаем список избранных товаров из cookies
    favorites_ids = json.loads(favorites_ids)  # Преобразуем в список
    coins = Coin.objects.filter(id__in=favorites_ids)  # Находим монеты по этим id
    return render(request, 'shop/favorites.html', {'coins': coins})

def cart_view(request):
    cart = request.session.get('cart', {})
    items = []
    total = 0
    for coin_id, qty in cart.items():
        coin = Coin.objects.get(id=coin_id)
        items.append({'coin': coin, 'quantity': qty, 'subtotal': qty * coin.price})
        total += qty * coin.price
    return render(request, 'shop/cart.html', {'items': items, 'total': total})


def catalog_view(request):
    # Отримання параметрів GET
    selected_category = request.GET.get('category')
    selected_material = request.GET.get('material')
    selected_year = request.GET.get('year')

    # Початковий queryset
    coins = Coin.objects.all()

    # Фільтрація
    if selected_category:
        coins = coins.filter(category=selected_category)
    if selected_material:
        coins = coins.filter(material=selected_material)
    if selected_year:
        coins = coins.filter(year=selected_year)

    # Дані для фільтра
    category_choices = Coin.CATEGORY_CHOICES
    materials = Coin.objects.values_list('material', flat=True).distinct()
    years = Coin.objects.values_list('year', flat=True).distinct().order_by('-year')

    context = {
        'coins': coins,
        'category_choices': category_choices,
        'materials': materials,
        'years': years,
    }
    return render(request, 'shop/index.html', context)
@csrf_exempt
def api_create_order(request):
    if request.method != 'POST':
        return JsonResponse({'success': False, 'error': 'Only POST allowed'})
    try:
        data = json.loads(request.body)
        lastname = data.get('lastname')
        firstname = data.get('firstname')
        name = f"{lastname} {firstname}"
        phone = data.get('phone')
        comment = data.get('comment')
        city = data.get('city')
        np_office = data.get('np_office')
        payment = data.get('payment')
        bank = data.get('bank')
        cart = data.get('cart', {})
        order = Order.objects.create(
            name=name, phone=phone, comment=comment,
            city=city, np_office=np_office, payment=payment, bank=bank
        )
        for cid, obj in cart.items():
            coin = Coin.objects.get(id=cid)
            qty = obj.get('quantity', 1)
            OrderItem.objects.create(order=order, product=coin, quantity=qty, price=coin.price)
        return JsonResponse({'success': True})
    except Exception as e:
        return JsonResponse({'success': False, 'error': str(e)})

def cart_view(request):
    coins = Coin.objects.all()
    coins_json = json.dumps([
        {'id': c.id, 'name': c.name, 'price': float(c.price), 'image': c.image.url if c.image else ''}
        for c in coins
    ])
    return render(request, 'shop/cart.html', {
        'coins_json': coins_json,
        'csrf_token': request.COOKIES.get('csrftoken'),
    })
@csrf_exempt
def np_proxy(request):
    if request.method == "POST":
        r = requests.post(
            "https://api.novaposhta.ua/v2.0/json/",
            data=request.body,
            headers={"Content-Type": "application/json"}
        )
        return JsonResponse(r.json())
    return JsonResponse({"error": "Only POST allowed"}, status=405)
