def category_detail(request, slug):
    # Определяем: монеты или банкноты
    if slug in [c[0] for c in Coin.CATEGORY_CHOICES]:
        products = Coin.objects.filter(category=slug)
        template = "shop/category_coins.html"
    elif slug in [b[0] for b in Banknote.CATEGORY_CHOICES]:
        products = Banknote.objects.filter(category=slug)
        template = "shop/category_banknotes.html"
    else:
        # Если категории нет, 404
        from django.http import Http404
        raise Http404("Категорія не знайдена")

    return render(request, template, {
        "products": products,
        "slug": slug,
    })
@require_GET
def ajax_search_coins(request):
    q = request.GET.get('q', '').strip()
    results = []
    if len(q) >= 2:
        qs = Coin.objects.filter(name__icontains=q)[:8]
        for c in qs:
            results.append({
                'id': c.id,
                'name': c.name,
                'image': c.image.url if c.image else '',
                'year': c.year,
                'material': c.material,
                'price': float(c.price),
                'circulation': c.circulation,
            })
    return JsonResponse({'results': results})
def banknote_catalog_view(request):
    selected_category = request.GET.get('category')
    selected_material = request.GET.get('material')
    selected_year = request.GET.get('year')

    banknotes = Banknote.objects.all()

    if selected_category:
        banknotes = banknotes.filter(category=selected_category)
    if selected_material:
        banknotes = banknotes.filter(material=selected_material)
    if selected_year:
        banknotes = banknotes.filter(year=selected_year)

    category_choices = Banknote.CATEGORY_CHOICES
    materials = Banknote.objects.values_list('material', flat=True).distinct()
    years = Banknote.objects.values_list('year', flat=True).distinct().order_by('-year')

    context = {
        'banknotes': banknotes,
        'category_choices': category_choices,
        'materials': materials,
        'years': years,
    }
    return render(request, 'shop/banknote_catalog.html', context)

def universal_catalog_view(request, item_type):
    Model = Coin if item_type == 'coin' else Banknote

    selected_category = request.GET.get('category')
    selected_material = request.GET.get('material')
    selected_year = request.GET.get('year')

    items = Model.objects.all()
    if selected_category:
        items = items.filter(category=selected_category)
    if selected_material:
        items = items.filter(material=selected_material)
    if selected_year:
        items = items.filter(year=selected_year)

    category_choices = Model.CATEGORY_CHOICES
    materials = Model.objects.values_list('material', flat=True).distinct()
    years = Model.objects.values_list('year', flat=True).distinct().order_by('-year')

    context = {
        'items': items,
        'category_choices': category_choices,
        'materials': materials,
        'years': years,
        'item_type': item_type,
    }
    return render(request, f'shop/{item_type}_catalog.html', context)

@csrf_exempt
def telegram_webhook(request):
    if request.method == 'POST':
        data = json.loads(request.body)
        message = data.get('message', {})
        chat = message.get('chat', {})
        chat_id = chat.get('id')
        if chat_id:
            # Здесь сохраняем chat_id пользователя в базу
            from .models import TelegramUser
            TelegramUser.objects.get_or_create(chat_id=chat_id)
        # ... остальная логика, если нужна
        return JsonResponse({"ok": True})